// SCENARIO — the whole test harness is `gv.assert`: it throws on the first
// failure, so silence is a pass. Run it from the Scripts view, or with
//
//   grpcview script run smoke --collection example
//
// Every request it drives is a SAVED one, invoked through the same pipeline the
// UI uses — bodies, metadata, folder inheritance and middleware all included.
// The one request it cannot drive is Workspace/Streaming/InvokeStreaming:
// gv.invoke refuses a streaming path outright.

const listed = await gv.invoke("Workspace/ListCollections");
gv.assert("a request with no target of its own invokes", listed.ok);
gv.assert(
  "grpcview lists the collection this scenario lives in",
  listed.body.collections.some((c: { id: string }) => c.id === "example"),
);

// Folder metadata is inherited even though the request never spreads it itself.
gv.assert(
  "the Workspace folder's metadata is inherited",
  listed.requestMetadata["x-demo-suite"][0] === "workspace",
);

// A plain protojson body — valid JSON is already valid TypeScript.
const described = await gv.invoke("Workspace/DescribeMethod (JSON)");
gv.assert("a plain protojson body invokes", described.ok);
gv.assert(
  "the bazel source wins over reflection",
  described.body.sourceId === "bazel://proto/grpcview/v1:grpcviewv1_proto",
);
gv.assert(
  "and its descriptor kept the .proto doc comments reflection strips",
  described.body.protoText.includes("Deliberately cheap"),
);

// The second argument of gv.invoke lands in the target's gv.request.params.
const params = await gv.invoke("Workspace/RunScript (params)", { expression: "6 * 7" });
gv.assert("params reach the target's body", params.body.value === "42");

// Generators compose: this request's body and its metadata both call them.
const generated = await gv.invoke("Workspace/RunScript (generators)");
gv.assert(
  "the generator-built id round-trips through the server",
  /^"gv_[0-9a-f]{12} at 2022-01-01T00:00:00Z"$/.test(generated.body.value),
);
gv.assert(
  "dayjs runs on the sandbox's pinned clock",
  generated.requestMetadata["x-sent-at"][0] === "2022-01-01T00:00:00Z",
);

// Middleware runs last, on the outgoing message.
const traced = await gv.invoke("Workspace/RunScript (middleware)");
gv.assert(
  "middleware rewrote the body",
  traced.body.value === '"[traced] before middleware"',
);
gv.assert("middleware stamped a trace id", traced.requestMetadata["x-trace-id"][0].length > 0);

// gv.invoke chaining: a body that invokes another saved request to build itself,
// asking grpcview to then call grpcview again.
const chained = await gv.invoke("Workspace/Invoke (chained)");
gv.assert("the chained body resolved and invoked", chained.ok);
gv.assert("the inner call came back with a response", chained.body.response.response.length > 0);

"13 assertions passed"
